
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_xc_br3p86_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_xc_br3p86", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.824911355526770e+00, -2.806747917120715e+00, -2.777788959149027e+00, -2.731182329631725e+00, -2.656167286385950e+00, -2.537009850387394e+00, -2.353462252681502e+00, -2.087052115577593e+00, -1.738579267806639e+00, -1.339722261976178e+00, -9.278715628334414e-01, -5.944605089169767e-01, -4.941881924895593e-01, -4.240614850871280e-01, -3.222277824587778e-01, -2.097666253855653e-01, -1.272179289827989e-01, -8.696873922555030e-02, -5.429920856087427e-02, -3.492799544457670e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


